def isIsomorphic(s, t):
    if len(s) != len(t): return False
    s_to_t, t_to_s = {}, {}
    for c1, c2 in zip(s, t):
        if (c1 in s_to_t and s_to_t[c1] != c2) or (c2 in t_to_s and t_to_s[c2] != c1):
            return False
        s_to_t[c1] = c2
        t_to_s[c2] = c1
    return True

